"""Анимация: бегущая волна. Кадр рисуется целиком, в эмуляторе это около кадра в секунду."""
import numpy as np
from matplotlib.animation import FuncAnimation


def draw(fig):
    x = np.linspace(0, 2 * np.pi, 120)
    ax = fig.add_subplot()
    line, = ax.plot(x, np.sin(x))
    ax.set_ylim(-1.2, 1.2)
    ax.set_title("Бегущая волна")

    def step(i):
        line.set_ydata(np.sin(x + i / 5))
        return line,

    return FuncAnimation(fig, step, interval=200, cache_frame_data=False)


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
